<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import PersonalLedgerNav from '../components/PersonalLedgerNav.vue'
import { useWorkspaceStore } from '../stores/workspace'
import { useAuthStore } from '../stores/auth'
const route=useRoute(),router=useRouter(),workspace=useWorkspaceStore(),auth=useAuthStore()
const open=ref(false),mode=ref<'expense'|'income'|'subscription'>('expense'),saving=ref(false),loadError=ref('')
const form=reactive({title:'',amount:'',currency:auth.record?.defaultCurrency||'TWD',category:'',date:'',notes:'',billingCycle:'monthly'})
const today=()=>new Date().toISOString().slice(0,10)
const date=computed(()=>String(route.query.date||workspace.personalLedger?.date||today()))
const ledger=computed(()=>workspace.personalLedger),items=computed(()=>ledger.value?.items||[])
const label=computed(()=>{const d=new Date(date.value+'T12:00:00');return Number.isNaN(d.getTime())?date.value:new Intl.DateTimeFormat('zh-TW',{month:'long',day:'numeric',weekday:'short'}).format(d)})
const money=(n:number,c:string)=>c+' '+(n/100).toLocaleString('zh-TW',{minimumFractionDigits:2,maximumFractionDigits:2})
function move(days:number){const d=new Date(date.value+'T12:00:00');d.setDate(d.getDate()+days);router.replace({query:{...route.query,date:d.toISOString().slice(0,10)}})}
function resetDate(){router.replace({query:{...route.query,date:undefined}})}
function show(next:'expense'|'income'|'subscription'='expense'){mode.value=next;form.title='';form.amount='';form.category='';form.notes='';form.date=date.value;form.currency=auth.record?.defaultCurrency||'TWD';open.value=true}
async function submit(){if(!form.title.trim()||!Number.isFinite(Number(form.amount))||Number(form.amount)<0)return;saving.value=true;const amount=Math.round(Number(form.amount)*100),occurred=(form.date||date.value)+'T12:00:00.000Z';try{if(mode.value==='income')await workspace.addIncome({title:form.title.trim(),amountMinor:amount,currency:form.currency,category:form.category,receivedOn:occurred,notes:form.notes});else if(mode.value==='subscription')await workspace.addPersonalSubscription({name:form.title.trim(),amountMinor:amount,currency:form.currency,category:form.category,status:'active',billingCycle:form.billingCycle as any,billingInterval:1,startsOn:occurred,nextBilling:occurred,notes:form.notes,paidBy:auth.record?.id||''});else await workspace.addPersonalExpense({title:form.title.trim(),amountMinor:amount,currency:form.currency,category:form.category,paidBy:auth.record?.id||'',incurredOn:occurred,notes:form.notes});if(!workspace.error)open.value=false}finally{saving.value=false}}
async function deleteIncome(id?:string){if(id&&window.confirm('\u78ba\u5b9a\u522a\u9664\u6b64\u7b46\u6536\u5165？'))await workspace.deleteIncome(id)}
async function loadLedger(value:string){if(typeof workspace.refreshPersonalLedger!=='function')return;try{loadError.value='';await workspace.refreshPersonalLedger(value)}catch(reason){loadError.value=reason instanceof Error?reason.message:'Unable to load ledger'}}
watch(()=>route.query.date,v=>{void loadLedger(String(v||''))})
onMounted(()=>{void loadLedger(String(route.query.date||''))})
</script>
<template>
<div class="page personal-ledger-page"><PersonalLedgerNav/>
<header class="ledger-header"><div><p class="eyebrow">PERSONAL LEDGER</p><h1>&#x500b;&#x4eba;&#x5e33;&#x7c3f;</h1><p class="muted">&#x4e00;&#x5929;&#x4e00;&#x9801;，&#x6e05;&#x695a;&#x638c;&#x63e1;&#x652f;&#x51fa;、&#x6536;&#x5165;&#x8207;&#x8a02;&#x95b1;&#x6263;&#x6b3e;。</p></div><button class="primary ledger-add-desktop" @click="show()">＋ &#x65b0;&#x589e;&#x7d00;&#x9304;</button></header>
<section class="ledger-datebar card"><button class="icon-button" @click="move(-1)">‹</button><div class="ledger-date-copy"><strong>{{label}}</strong><span>{{ledger?.timezone||auth.record?.timezone||'&#x5e33;&#x865f;&#x6642;&#x5340;'}} · {{date}}</span></div><button class="icon-button" @click="move(1)">›</button><button v-if="date!==today()" class="ghost today-button" @click="resetDate">&#x56de;&#x5230;&#x4eca;&#x5929;</button></section>
<p v-if="workspace.error||loadError" class="inline-error">{{loadError||workspace.error}}</p>
<section v-if="ledger" class="ledger-summary-grid"><article v-for="s in ledger.summaries" :key="s.currency" class="ledger-summary card"><div class="summary-top"><span>{{s.currency}}</span><span>{{s.count}} &#x7b46;</span></div><strong>{{money(s.netMinor,s.currency)}}</strong><div class="summary-lines"><span class="income">&#x6536;&#x5165; {{money(s.incomeMinor,s.currency)}}</span><span class="expense">&#x652f;&#x51fa; {{money(s.expenseMinor,s.currency)}}</span><span class="subscription">&#x8a02;&#x95b1; {{money(s.subscriptionMinor,s.currency)}}</span></div></article><article v-if="!ledger.summaries.length" class="ledger-summary card empty-summary"><strong>&#x4eca;&#x5929;&#x9084;&#x6c92;&#x6709;&#x7d00;&#x9304;</strong><span>&#x7528;&#x4e0b;&#x65b9;&#x6309;&#x9215;&#x5feb;&#x901f;&#x8a18;&#x4e00;&#x7b46;。</span></article></section>
<section class="ledger-list card"><div class="section-heading"><div><p class="eyebrow">TIMELINE</p><h2>&#x4eca;&#x65e5;&#x7d00;&#x9304;</h2></div><span>{{items.length}} &#x7b46;</span></div><div v-if="!items.length" class="ledger-empty"><div class="empty-icon">✦</div><strong>&#x5f9e;&#x7b2c;&#x4e00;&#x7b46;&#x7d00;&#x9304;&#x958b;&#x59cb;</strong><p>&#x652f;&#x51fa;、&#x6536;&#x5165;&#x6216;&#x8a02;&#x95b1;&#x90fd;&#x80fd;&#x5728;&#x9019;&#x88e1;&#x5feb;&#x901f;&#x52a0;&#x5165;。</p></div><article v-for="item in items" :key="item.id" class="ledger-item" :class="'kind-'+item.kind+' status-'+item.status"><div class="item-icon">{{item.kind==='income'?'↗':item.kind==='subscription'?'↻':'−'}}</div><div class="item-main"><strong>{{item.title}}</strong><span>{{item.category||'&#x672a;&#x5206;&#x985e;'}} · {{item.status==='scheduled'?'&#x5f85;&#x6263;&#x6b3e;':item.status==='failed'?'&#x540c;&#x6b65;&#x5931;&#x6557;':item.status==='pending'?'&#x540c;&#x6b65;&#x4e2d;':'&#x5df2;&#x5165;&#x5e33;'}}</span><small v-if="item.notes">{{item.notes}}</small></div><div class="item-side"><strong :class="item.kind==='income'?'income':'expense'">{{item.kind==='income'?'+':'−'}}{{money(item.amountMinor,item.currency)}}</strong><time>{{new Date(item.occurredAt).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})}}</time><button v-if="item.kind==='income'&&item.recordId" class="text-button" @click="deleteIncome(item.recordId)">&#x522a;&#x9664;</button></div></article></section>
<button class="ledger-fab" @click="show()" aria-label="&#x65b0;&#x589e;&#x7d00;&#x9304;">＋</button>
<div v-if="open" class="drawer-backdrop" @click.self="open=false"><section class="ledger-drawer" role="dialog" aria-modal="true"><div class="drawer-handle"></div><div class="drawer-title"><div><p class="eyebrow">QUICK ADD</p><h2>&#x65b0;&#x589e;&#x7d00;&#x9304;</h2></div><button class="icon-button" @click="open=false">×</button></div><div class="mode-tabs"><button :class="{active:mode==='expense'}" @click="mode='expense'">&#x652f;&#x51fa;</button><button :class="{active:mode==='income'}" @click="mode='income'">&#x6536;&#x5165;</button><button :class="{active:mode==='subscription'}" @click="mode='subscription'">&#x8a02;&#x95b1;</button></div><form class="ledger-form" @submit.prevent="submit"><label>&#x540d;&#x7a31;<input v-model="form.title" required placeholder="&#x4f8b;&#x5982;：&#x5348;&#x9910;、&#x85aa;&#x8cc7;&#x6216;&#x5f71;&#x97f3;&#x8a02;&#x95b1;"/></label><div class="form-row"><label>&#x91d1;&#x984d;<input v-model="form.amount" type="number" min="0" step="0.01" required/></label><label>&#x5e63;&#x5225;<select v-model="form.currency"><option>TWD</option><option>USD</option><option>JPY</option><option>EUR</option></select></label></div><label>&#x5206;&#x985e;<input v-model="form.category" placeholder="&#x53ef;&#x9078;"/></label><label v-if="mode==='subscription'">&#x9031;&#x671f;<select v-model="form.billingCycle"><option value="monthly">&#x6bcf;&#x6708;</option><option value="yearly">&#x6bcf;&#x5e74;</option><option value="weekly">&#x6bcf;&#x9031;</option></select></label><label>&#x65e5;&#x671f;<input v-model="form.date" type="date" required/></label><label>&#x5099;&#x8a3b;<textarea v-model="form.notes" rows="2"/></label><button class="primary full-width" :disabled="saving">{{saving?'&#x5132;&#x5b58;&#x4e2d;…':'&#x5132;&#x5b58;&#x7d00;&#x9304;'}}</button></form></section></div>
</div>
</template>
<style scoped>
.personal-ledger-page{max-width:1120px;margin:auto;padding-bottom:2rem}.ledger-header{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin:2rem 0 1.5rem}.ledger-header h1{margin:.25rem 0;font-size:clamp(2rem,5vw,3.4rem)}.ledger-datebar{display:flex;align-items:center;gap:1rem;padding:1rem 1.25rem;margin-bottom:1rem}.ledger-date-copy{display:flex;flex:1;flex-direction:column;text-align:center}.ledger-date-copy strong{font-size:1.2rem}.ledger-date-copy span,.summary-top,.item-main span,.item-main small,.item-side time{color:var(--muted);font-size:.82rem}.icon-button{border:0;background:transparent;color:inherit;font-size:1.8rem;padding:.25rem .6rem;cursor:pointer}.today-button{white-space:nowrap}.ledger-summary-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;margin-bottom:1rem}.ledger-summary{padding:1.2rem}.summary-top{display:flex;justify-content:space-between}.ledger-summary>strong{display:block;font-size:1.65rem;margin:.65rem 0}.summary-lines{display:grid;gap:.25rem;font-size:.8rem}.income{color:#72d6ad}.expense{color:#ff9b9b}.subscription{color:#aaa4ff}.ledger-list{padding:1.25rem}.section-heading,.drawer-title{display:flex;justify-content:space-between;align-items:center}.section-heading h2,.drawer-title h2{margin:.2rem 0 1rem}.section-heading>span{color:var(--muted)}.ledger-item{display:flex;align-items:center;gap:.8rem;padding:1rem 0;border-top:1px solid var(--border)}.item-icon{display:grid;place-items:center;width:2.5rem;height:2.5rem;border-radius:50%;background:var(--surface-strong);font-size:1.3rem}.item-main{display:grid;gap:.2rem;flex:1;min-width:0}.item-main strong{overflow:hidden;text-overflow:ellipsis}.item-main small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.item-side{text-align:right;display:grid;gap:.2rem;justify-items:end}.item-side strong{white-space:nowrap}.text-button{background:none;border:0;color:var(--muted);cursor:pointer;font-size:.75rem}.ledger-empty,.empty-summary{text-align:center;padding:2.5rem;color:var(--muted)}.empty-summary{display:flex;flex-direction:column;gap:.4rem}.empty-summary strong,.ledger-empty strong{color:var(--text)}.empty-icon{font-size:2rem}.ledger-fab{display:none}.drawer-backdrop{position:fixed;inset:0;background:#05071199;z-index:50;display:flex;align-items:flex-end;justify-content:center}.ledger-drawer{width:min(560px,100%);max-height:90dvh;overflow:auto;background:var(--surface);border:1px solid var(--border);border-radius:24px 24px 0 0;padding:1rem 1.25rem calc(1.25rem + env(safe-area-inset-bottom));box-shadow:0 -20px 60px #0008}.drawer-handle{width:44px;height:4px;background:var(--muted);opacity:.5;border-radius:99px;margin:0 auto 1rem}.mode-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:.4rem;background:var(--surface-strong);padding:.3rem;border-radius:12px;margin-bottom:1.1rem}.mode-tabs button{border:0;background:none;color:var(--muted);padding:.65rem;border-radius:9px;cursor:pointer}.mode-tabs button.active{background:var(--accent);color:white}.ledger-form{display:grid;gap:.8rem}.ledger-form label{display:grid;gap:.35rem;color:var(--muted);font-size:.85rem}.ledger-form input,.ledger-form select,.ledger-form textarea{width:100%;box-sizing:border-box;border:1px solid var(--border);border-radius:10px;background:var(--surface-strong);color:var(--text);padding:.75rem;font:inherit}.form-row{display:grid;grid-template-columns:1fr .7fr;gap:.7rem}.full-width{width:100%}.inline-error{color:#ff9b9b;margin:.7rem 0}
@media(max-width:900px){.personal-ledger-page{padding:1rem 1rem calc(7rem + env(safe-area-inset-bottom))}.ledger-header{margin:1rem 0;align-items:flex-start}.ledger-add-desktop{display:none}.ledger-fab{display:block;position:fixed;right:1.1rem;bottom:calc(88px + env(safe-area-inset-bottom));z-index:30;width:3.5rem;height:3.5rem;border:0;border-radius:50%;background:var(--accent);color:white;font-size:1.7rem;box-shadow:0 10px 30px #0008}.ledger-datebar{padding:.8rem}.today-button{font-size:.75rem;padding:.45rem}.ledger-summary-grid{grid-template-columns:1fr 1fr;gap:.65rem}.ledger-summary{padding:.85rem}.ledger-summary>strong{font-size:1.15rem}.summary-lines{font-size:.7rem}.section-heading h2{font-size:1.25rem}}
@media(max-width:420px){.ledger-summary-grid{grid-template-columns:1fr}.form-row{grid-template-columns:1fr 1fr}}
</style>